/**
 * 新建工作空间三步向导：① 名称 + 主目录保存位置（base 路径）→ ② 选择文件夹自动识别
 * 项目（可多选、可多次选择累加）→ ③ 完成。保存时在 base 路径下创建与名称同名的文件夹作为主目录，
 * 第二步选中的项目作为代码项目加入工作空间。
 * @module dsh-workspace-combiner/client/panel/NewWorkspaceWizard
 */

import { useRef, useState, type ChangeEvent, type ReactElement } from 'react'
import type { DetectedProject, LoadMode, WorkspaceMode, WorkspaceRef } from '../../core/types.ts'
import { DEFAULT_WORKSPACE_NAME } from '../../invariant.ts'
import { WorkspaceCombinerApi } from '../api.ts'
import { tt } from '../locales.ts'
import { joinPath, rememberBasePath } from './defaults.ts'
import { Dialog } from './Dialog.tsx'
import { groupKindOf, groupLabel } from './groups.ts'
import { sanitizeWorkspaceName } from './naming.ts'
import { TypeBadge } from './typeBadge.tsx'

interface NewWorkspaceWizardProps {
  /** 预填的主目录保存位置（上次用过 / 由现有工作空间推导）；空串表示没有可用的默认值。 */
  defaultBasePath?: string
  pickDirectory: () => Promise<string | null>
  onClose: () => void
  onCreate: (name: string, basePath: string, directories: readonly WorkspaceRef[], mode: WorkspaceMode, loadMode: LoadMode) => void
}

export function NewWorkspaceWizard({ defaultBasePath = '', pickDirectory, onClose, onCreate }: NewWorkspaceWizardProps): ReactElement {
  const apiRef = useRef<WorkspaceCombinerApi | null>(null)
  if (apiRef.current === null) apiRef.current = new WorkspaceCombinerApi()

  const [step, setStep] = useState<1 | 2 | 3>(1)
  const [name, setName] = useState('')
  // 预填默认保存位置：多数情况直接「下一步」即可，不必每次点选择文件夹。
  const [basePath, setBasePath] = useState(defaultBasePath)
  const [scanPath, setScanPath] = useState('')
  const [scanning, setScanning] = useState(false)
  const [projects, setProjects] = useState<readonly DetectedProject[]>([])
  const [checked, setChecked] = useState<Set<string>>(new Set())
  const [mode, setMode] = useState<WorkspaceMode>('anchor')
  // 第二步支持多次添加：跨多次扫描按 root 去重，新识别到的项目自动勾选并追加到列表。
  const knownRootsRef = useRef<Set<string>>(new Set())
  /** 扫描请求序号：过期响应直接丢弃（连续选多个文件夹时不会串台）。 */
  const scanSeqRef = useRef(0)
  const [scanNote, setScanNote] = useState<{ added: number; dup: number } | null>(null)

  const pickBase = (): void => {
    void pickDirectory()
      .then(path => {
        const trimmed = path?.trim() ?? ''
        if (trimmed === '') return
        setBasePath(trimmed)
        rememberBasePath(trimmed)
      })
      .catch(() => {})
  }

  const runScan = (path: string): void => {
    const api = apiRef.current
    if (api === null) return
    const seq = ++scanSeqRef.current
    setScanning(true)
    void api.scan(path)
      .then(list => {
        if (seq !== scanSeqRef.current) return
        // 只追加此前没出现过的项目：重复扫描同一文件夹不会再产生重复条目。
        const fresh = list.filter(p => !knownRootsRef.current.has(p.root))
        for (const p of fresh) knownRootsRef.current.add(p.root)
        if (fresh.length > 0) {
          setProjects(prev => [...prev, ...fresh])
          setChecked(prev => {
            const next = new Set(prev)
            for (const p of fresh) next.add(p.root)
            return next
          })
        }
        setScanNote({ added: fresh.length, dup: list.length - fresh.length })
      })
      .catch(() => { if (seq === scanSeqRef.current) setScanNote(null) })
      // 只有最新一次扫描才有权把按钮恢复可用，否则先完成的那个会提前解锁。
      .finally(() => { if (seq === scanSeqRef.current) setScanning(false) })
  }

  const pickScan = (): void => {
    void pickDirectory()
      .then(path => {
        if (path !== null && path.trim() !== '') {
          const trimmed = path.trim()
          setScanPath(trimmed)
          runScan(trimmed)
        }
      })
      .catch(() => {})
  }

  const toggle = (root: string): void => {
    setChecked(prev => {
      const next = new Set(prev)
      if (next.has(root)) next.delete(root)
      else next.add(root)
      return next
    })
  }
  const allChecked = projects.length > 0 && checked.size === projects.length
  const toggleAll = (): void => setChecked(allChecked ? new Set() : new Set(projects.map(p => p.root)))

  const finalName = name.trim() === '' ? DEFAULT_WORKSPACE_NAME : name.trim()
  // 预览用：名称会先做规范化（去掉非法字符），再作为文件夹名。
  const sanitizedName = sanitizeWorkspaceName(finalName)
  const folderName = sanitizedName === '' ? finalName : sanitizedName
  const selected = projects.filter(p => checked.has(p.root))
  const suggestedLoadMode: LoadMode = selected.length > 0 && selected.length <= 4 ? 'tree' : 'summary'
  // 识别出的项目顺带带上自动分组、访问模式与真实脚本命令；创建后仍可逐项修改。
  const buildSecondaryRefs = (): WorkspaceRef[] => selected.map(p => ({
    id: p.root, name: p.name, path: p.root, projectType: p.type, evidence: p.evidence,
    access: 'readwrite', group: groupKindOf(p.suggestedGroup) ?? 'other',
    ...(p.commands === undefined ? {} : { commands: p.commands }),
    ...(p.monorepo === undefined ? {} : { monorepo: p.monorepo }),
  }))

  return (
    <Dialog title={tt('wizardTitle')} onClose={onClose} wide>

        <div className="wcb-steps">
          {[tt('wizardStep1'), tt('wizardStep2'), tt('wizardStep3')].map((label, i) => {
            const n = i + 1
            return (
              <div key={label} className={'wcb-step' + (step === n ? ' wcb-step-active' : '') + (step > n ? ' wcb-step-done' : '')}>
                <span className="wcb-step-num">{n}</span>
                <span>{label}</span>
              </div>
            )
          })}
        </div>

        {step === 1 ? (
          <div className="wcb-wizard-body">
            <label className="wcb-field">
              <span>{tt('wsCreateName')}</span>
              <input className="wcb-input" value={name} autoFocus placeholder={tt('wizardNamePlaceholder')} onChange={(event: ChangeEvent<HTMLInputElement>) => setName(event.currentTarget.value)} />
            </label>
            <label className="wcb-field">
              <span>{tt('wizardBaseDir')}</span>
              <div className="wcb-add-row">
                <button type="button" className="wcb-btn" onClick={pickBase}>{tt('wizardPickFolder')}</button>
                <input
                  className="wcb-input"
                  value={basePath}
                  placeholder={tt('wizardBaseEmpty')}
                  aria-label={tt('wizardBaseDir')}
                  onChange={(event: ChangeEvent<HTMLInputElement>) => setBasePath(event.currentTarget.value)}
                  onBlur={() => rememberBasePath(basePath)}
                />
              </div>
            </label>
            {basePath.trim() === '' ? null : (
              <div className="wcb-hint">{tt('wizardMainDirPreview', { path: joinPath(basePath, folderName) })}</div>
            )}
            <div>
              <div className="wcb-label">{tt('wsModeLabel')}</div>
              <div className="wcb-tabs" role="tablist" aria-label={tt('wsModeLabel')}>
                {([['anchor', tt('wsModeAnchor')], ['single', tt('wsModeSingle')]] as Array<[WorkspaceMode, string]>).map(([value, label]) => (
                  <button key={value} type="button" role="tab" aria-selected={mode === value} aria-label={label} className={'wcb-tab' + (mode === value ? ' wcb-tab-on' : '')} onClick={() => setMode(value)}>{label}</button>
                ))}
              </div>
            </div>
            <div className="wcb-hint">{mode === 'single' ? tt('wsModeSingleHint') : tt('wsModeAnchorHint')}</div>
            <div className="wcb-hint">{tt('wizardBaseHint')}</div>
          </div>
        ) : null}

        {step === 2 ? (
          <div className="wcb-wizard-body">
            <div className="wcb-add-row">
              <button type="button" className="wcb-btn" disabled={scanning} onClick={pickScan}>{projects.length > 0 ? tt('wizardPickMore') : tt('wizardPickFolder')}</button>
              <div className="wcb-pathbox">{scanPath === '' ? tt('wizardScanFolderEmpty') : scanPath}</div>
            </div>
            <div className="wcb-hint">{tt('wizardMultiHint')}</div>
            {scanning ? <div className="wcb-hint">{tt('wizardScanning')}</div> : null}
            {!scanning && scanNote !== null ? (
              <div className="wcb-hint">
                {scanNote.added > 0
                  ? tt('wizardScanAdded', { n: scanNote.added, total: projects.length })
                  : scanNote.dup > 0 ? tt('wizardScanDup', { n: scanNote.dup }) : tt('wizardNoProject')}
              </div>
            ) : null}
            {!scanning && projects.length > 0 ? (
              <>
                <div className="wcb-toolbar">
                  <button type="button" className="wcb-btn" onClick={toggleAll}>{allChecked ? tt('wizardClearSelect') : tt('wizardSelectAll')}</button>
                </div>
                <ul className="wcb-scan-list">
                  {projects.map(p => (
                    <li key={p.root} className="wcb-scan-item">
                      <input type="checkbox" checked={checked.has(p.root)} aria-label={p.name} onChange={() => toggle(p.root)} />
                      <div className="wcb-scan-info">
                        <div className="wcb-scan-name">{p.name}</div>
                        <div className="wcb-scan-path" title={p.root}>{p.root}</div>
                        <div className="wcb-scan-defaults">
                          {p.monorepo !== undefined ? <span>{tt('wizardMonorepo', { kind: p.monorepo.kind, n: p.monorepo.packages.length })}</span> : null}
                          <span>{tt('wizardAutoGroup', { group: groupLabel(groupKindOf(p.suggestedGroup) ?? 'other') })}</span>
                          <span>{p.commands === undefined ? tt('wizardNoCommandDefault') : tt('wizardCommandDefaults', { n: Object.keys(p.commands).length })}</span>
                        </div>
                      </div>
                      <TypeBadge type={p.type} evidence={p.evidence} />
                    </li>
                  ))}
                </ul>
              </>
            ) : null}
          </div>
        ) : null}

        {step === 3 ? (
          <div className="wcb-wizard-body">
            <div className="wcb-hint">{tt('wizardSummary', { name: finalName, base: basePath, n: selected.length })}</div>
            <div className="wcb-smart-defaults">
              <strong>{tt('wizardSmartDefaults')}</strong>
              <span>{tt('wizardSuggestedLoadMode', { mode: suggestedLoadMode === 'tree' ? tt('loadModeTree') : tt('loadModeSummary') })}</span>
              <span>{tt('wizardDefaultsEditable')}</span>
            </div>
          </div>
        ) : null}

        <div className="wcb-modal-actions">
          {step > 1 ? <button type="button" className="wcb-btn-plain" aria-label={tt('wizardBack')} onClick={() => setStep((step - 1) as 1 | 2 | 3)}>{tt('wizardBack')}</button> : null}
          <button type="button" className="wcb-btn-plain" aria-label={tt('cancel')} onClick={onClose}>{tt('cancel')}</button>
          {step < 3 ? (
            <button type="button" className="wcb-btn-primary" aria-label={tt('wizardNext')} disabled={step === 1 && basePath === ''} onClick={() => setStep((step + 1) as 1 | 2 | 3)}>{tt('wizardNext')}</button>
          ) : (
            <button type="button" className="wcb-btn-primary" aria-label={tt('wizardCreate')} disabled={basePath === ''} onClick={() => onCreate(finalName, basePath, buildSecondaryRefs(), mode, suggestedLoadMode)}>{tt('wizardCreate')}</button>
          )}
        </div>
    </Dialog>
  )
}
